import math

def count_band(n, start, low, high):
    # DP over a sliding window of width W0 = high - low + 1 using bitmasks
    W0 = high - low + 1
    if W0 <= 0:
        return 0
    # Precompute availability bitsets per row
    avail = []
    for i in range(1, n+1):
        row = [0] * W0
        for p in range(W0):
            j = i + low - start + 1 + p  # column index in 1..n corresponding to window position p
            if 1 <= j <= n:
                row[p] = 1
        avail.append(row)
    dp = {0: 1}
    for i in range(n):
        row = avail[i]
        new = {}
        for mask, val in dp.items():
            # try placing at any available, unused position in this row
            for p in range(W0):
                if row[p] and ((mask >> p) & 1) == 0:
                    m2 = mask | (1 << p)
                    next_mask = m2 >> 1  # window shifts right by 1
                    new[next_mask] = new.get(next_mask, 0) + val
        dp = new
        if not dp:
            return 0
    return sum(dp.values())

